document.addEventListener('click', function (e) {
  const link = e.target.closest('[data-tab-link]');
  if (!link) return;

  // Stop Webflow from switching the tab
  e.preventDefault();
  e.stopImmediatePropagation();

  const url = link.getAttribute('data-tab-link');
  if (link.getAttribute('data-tab-target') === '_blank') {
    window.open(url, '_blank');
  } else {
    window.location.href = url;
  }
}, true); // capture phase — runs before Webflow's tab handler

(function () {
  var MIN_THUMB = 28;

  function build(content) {
    if (content.dataset.customScroll) return;
    content.dataset.customScroll = '1';

    // wrap
    var wrap = document.createElement('div');
    wrap.className = 'team-scroll-wrap';
    content.parentNode.insertBefore(wrap, content);
    wrap.appendChild(content);

    var track = document.createElement('div');
    track.className = 'team-scrollbar';
    var thumb = document.createElement('div');
    thumb.className = 'team-scrollbar-thumb';
    track.appendChild(thumb);
    wrap.appendChild(track);

    var dragging = false,
      startY = 0,
      startScroll = 0,
      ratio = 1;

    function update() {
      var sh = content.scrollHeight,
        ch = content.clientHeight;
      if (sh <= ch + 1) {
        track.classList.remove('is-active');
        return;
      }
      track.classList.add('is-active');

      var trackH = track.clientHeight;
      var thumbH = Math.max(MIN_THUMB, trackH * (ch / sh));
      var maxScroll = sh - ch;
      var maxThumb = trackH - thumbH;
      ratio = maxScroll / maxThumb;

      thumb.style.height = thumbH + 'px';
      thumb.style.transform = 'translateY(' + content.scrollTop / ratio + 'px)';
    }

    content.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);

    // fires when the modal goes from hidden (0px) to visible
    if (window.ResizeObserver) {
      var ro = new ResizeObserver(update);
      ro.observe(content);
      if (content.firstElementChild) ro.observe(content.firstElementChild);
    }

    // drag
    thumb.addEventListener('pointerdown', function (e) {
      e.preventDefault();
      dragging = true;
      startY = e.clientY;
      startScroll = content.scrollTop;
      track.classList.add('is-dragging');
      thumb.setPointerCapture(e.pointerId);
    });
    thumb.addEventListener('pointermove', function (e) {
      if (!dragging) return;
      content.scrollTop = startScroll + (e.clientY - startY) * ratio;
    });
    ['pointerup', 'pointercancel'].forEach(function (evt) {
      thumb.addEventListener(evt, function (e) {
        dragging = false;
        track.classList.remove('is-dragging');
        if (thumb.hasPointerCapture(e.pointerId)) thumb.releasePointerCapture(e.pointerId);
      });
    });

    // click track to jump
    track.addEventListener('pointerdown', function (e) {
      if (e.target === thumb) return;
      var rect = track.getBoundingClientRect();
      var thumbH = thumb.offsetHeight;
      var target = (e.clientY - rect.top - thumbH / 2) * ratio;
      content.scrollTo({ top: target, behavior: 'smooth' });
    });

    update();
    content._refreshScrollbar = update;
  }

  function init() {
    document.querySelectorAll('.team-modal-content').forEach(build);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // call window.refreshTeamScrollbars() after injecting content dynamically
  window.refreshTeamScrollbars = function () {
    init();
    document.querySelectorAll('.team-modal-content').forEach(function (el) {
      if (el._refreshScrollbar) el._refreshScrollbar();
    });
  };
})();

document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('.session-coaching-form').forEach(function (form) {
    var select = form.querySelector('select');
    var input  = form.querySelector('input[type="submit"]');
    var buttonW = form.querySelector('.button-w');
    if (!select || !input || !buttonW) return;

    function sync() {
      var noneSelected = select.value === '';
      input.disabled = noneSelected;                       // blocks submission
      buttonW.classList.toggle('is-disabled', noneSelected); // visual state
    }

    select.addEventListener('change', sync);
    sync(); // set initial state on load
  });
});
